alter table profiles add column if not exists is_active boolean not null default true;
alter table profiles add column if not exists organization_id uuid;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),owner_user_id uuid references profiles(id) on delete restrict,name text not null,legal_name text,base_currency text not null references currencies(code) default 'SAR',entity_type text not null default 'FAMILY',status text not null default 'ACTIVE',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table profiles drop constraint if exists profiles_organization_id_fkey;
alter table profiles add constraint profiles_organization_id_fkey foreign key (organization_id) references organizations(id) on delete set null;
create table if not exists organization_members(organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,role text not null check(role in ('OWNER','ADMIN','ACCOUNTANT','ADVISOR','VIEWER','SHARIA_REVIEWER')),status text not null default 'ACTIVE',created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table if not exists organization_entities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,name text not null,entity_type text not null default 'PERSON',registration_no text,base_currency text not null references currencies(code) default 'SAR',zakat_method_id uuid references zakat_methods(id),nisab_standard text not null default 'SILVER',active boolean not null default true,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists consolidated_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,assessment_date date not null,valuation_date date not null,currency text not null references currencies(code),total_entity_value numeric(24,8) not null default 0,total_zakat_due numeric(24,8) not null default 0,status text not null default 'DRAFT',snapshot jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists organization_invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,email text not null,role text not null,token text unique not null default encode(gen_random_bytes(24),'hex'),expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,created_at timestamptz not null default now());
alter table asset_accounts add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table asset_accounts add column if not exists entity_id uuid references organization_entities(id) on delete set null;
alter table transactions add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table transactions add column if not exists entity_id uuid references organization_entities(id) on delete set null;
alter table lots add column if not exists organization_id uuid references organizations(id) on delete cascade;
alter table zakat_assessments add column if not exists organization_id uuid references organizations(id) on delete cascade; alter table zakat_assessments add column if not exists entity_id uuid references organization_entities(id) on delete set null;
create table if not exists sharia_rule_reviews(id uuid primary key default gen_random_uuid(),rule_id uuid not null references zakat_rules(id) on delete cascade,reviewer_id uuid references profiles(id),decision text not null default 'PENDING' check(decision in ('PENDING','APPROVED','REJECTED','CHANGES_REQUESTED')),notes text,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists rule_sources(id uuid primary key default gen_random_uuid(),rule_id uuid not null references zakat_rules(id) on delete cascade,source_title text not null,source_reference text,source_url text,scholar_name text,notes text,created_at timestamptz not null default now());
create table if not exists notification_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,notification_type text not null,scheduled_for timestamptz not null,status text not null default 'PENDING' check(status in ('PENDING','SENT','FAILED','CANCELLED')),attempts int not null default 0,last_error text,created_at timestamptz not null default now(),unique(user_id,notification_type,scheduled_for));
create table if not exists price_provider_configs(id uuid primary key default gen_random_uuid(),provider_name text not null,asset_class text not null,is_active boolean not null default true,configuration jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists idx_audit_entity on audit_logs(entity_type,entity_id,created_at desc); create index if not exists idx_notification_jobs on notification_jobs(status,scheduled_for);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,name,locale) values(new.id,coalesce(new.raw_user_meta_data->>'name',''),coalesce(new.raw_user_meta_data->>'locale','ar')) on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.has_role(p_user uuid,p_roles text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=p_user and is_active=true and role=any(p_roles)); $$;
insert into zakat_methods(code,name_ar,name_en,description_ar,description_en,calendar_type,zakat_rate,version) values ('INDEPENDENT_LOTS','حول مستقل لكل دفعة','Independent Lots','كل دفعة مؤهلة لها حول مستقل.','Each qualifying inflow has an independent hawl.','HIJRI',0.025,'1.0'),('UNIFIED_HAWL','حول موحد','Unified Hawl','حول موحد وفق الإعداد المعتمد.','Unified hawl according to configured methodology.','HIJRI',0.025,'1.0') on conflict(code) do nothing;